-- Synthetic fixture only, with deliberately broad legacy policies.
DO $$ BEGIN
 IF current_setting('footnation.attachments_test_disposable',true) IS DISTINCT FROM '1' OR to_regclass('public.messages') IS NOT NULL THEN
  RAISE EXCEPTION 'Fresh disposable database required';
 END IF;
END $$;
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth; CREATE SCHEMA storage;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
GRANT USAGE ON SCHEMA public,auth,storage TO authenticated,anon,service_role;
CREATE TABLE profiles(id uuid PRIMARY KEY,is_suspended boolean,suspended_until timestamptz,is_admin boolean);
CREATE TABLE user_blocks(blocker_id uuid,blocked_id uuid);
CREATE TABLE connections(user_id uuid,connected_user_id uuid,status text);
CREATE TABLE messages(id uuid PRIMARY KEY,sender_id uuid,receiver_id uuid,content text,is_blocked boolean DEFAULT false);
CREATE TABLE storage.buckets(id text PRIMARY KEY,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
CREATE TABLE storage.objects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bucket_id text,name text,metadata jsonb,created_at timestamptz DEFAULT now(),UNIQUE(bucket_id,name));
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
ALTER TABLE messages ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE,DELETE ON messages,storage.objects TO authenticated,anon,service_role;
GRANT SELECT ON storage.buckets TO authenticated,anon,service_role;
CREATE POLICY legacy_everything ON storage.objects FOR ALL TO PUBLIC USING(true) WITH CHECK(true);
CREATE POLICY legacy_messages ON messages FOR ALL TO authenticated USING(true) WITH CHECK(true);
