CREATE FUNCTION assert_attachment(value boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION 'Attachment assertion: %',label; END IF; END $$;
CREATE FUNCTION expect_attachment_error(command text,code text) RETURNS void LANGUAGE plpgsql AS $$ DECLARE actual text;
BEGIN
 BEGIN EXECUTE command; EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS actual=RETURNED_SQLSTATE;
  IF actual=code THEN RETURN; END IF; RAISE EXCEPTION 'Expected %, got %: %',code,actual,SQLERRM;
 END;
 RAISE EXCEPTION 'Forbidden operation succeeded';
END $$;
